1	package com.mailagent.agent;
2	
3	import com.mailagent.llm.ChatMessage;
4	import com.mailagent.llm.ChatResponse;
5	import com.mailagent.llm.ContentBlock;
6	import com.mailagent.llm.LlmClient;
7	import com.mailagent.llm.ToolSpec;
8	import com.mailagent.tools.ToolRegistry;
9	import org.slf4j.Logger;
10	import org.slf4j.LoggerFactory;
11	
12	import java.util.ArrayList;
13	import java.util.Arrays;
14	import java.util.List;
15	import java.util.stream.Collectors;
16	
17	/**
18	 * Drives the tool-calling conversation for a single unit of dialogue (one
19	 * email in, one final answer out). Bounded by maxSteps so a model that keeps
20	 * calling tools forever — or a broken/hallucinating one — can't hang the
21	 * poll loop; on that limit it returns a graceful fallback instead of the
22	 * (missing) final answer.
23	 */
24	public class ToolLoop {
25	
26	    private static final Logger log = LoggerFactory.getLogger(ToolLoop.class);
27	
28	    private final LlmClient llmClient;
29	    private final ToolRegistry toolRegistry;
30	    private final int maxSteps;
31	
32	    public ToolLoop(LlmClient llmClient, ToolRegistry toolRegistry, int maxSteps) {
33	        this.llmClient = llmClient;
34	        this.toolRegistry = toolRegistry;
35	        this.maxSteps = maxSteps;
36	    }
37	
38	    public String run(String systemPrompt, String userMessage) {
39	        List<ChatMessage> messages = new ArrayList<>();
40	        messages.add(ChatMessage.user(Arrays.asList(ContentBlock.text(systemPrompt), ContentBlock.text(userMessage))));
41	
42	        List<ToolSpec> toolSpecs = toolRegistry.tools().stream().map(ToolSpec::from).collect(Collectors.toList());
43	
44	        for (int step = 0; step < maxSteps; step++) {
45	            ChatResponse response = llmClient.chat(messages, toolSpecs);
46	            if (!response.hasToolUse()) {
47	                return response.textJoined();
48	            }
49	
50	            messages.add(ChatMessage.assistant(response.getContent()));
51	
52	            List<ContentBlock> toolResults = new ArrayList<>();
53	            for (ContentBlock toolUse : response.toolUseBlocks()) {
54	                String result = toolRegistry.dispatch(toolUse.getToolName(), toolUse.getToolInput());
55	                toolResults.add(ContentBlock.toolResult(toolUse.getToolUseId(), result));
56	            }
57	            messages.add(ChatMessage.user(toolResults));
58	        }
59	
60	        log.warn("tool_loop_max_steps_exceeded maxSteps={}", maxSteps);
61	        return "Sorry, I could not finish this request within the allotted number of steps.";
62	    }
63	}
64

