package com.mailagent.agent;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import com.mailagent.audit.AuditLogger;
import com.mailagent.llm.ChatResponse;
import com.mailagent.llm.ContentBlock;
import com.mailagent.llm.MockLlmClient;
import com.mailagent.mail.MockMailChannel;
import com.mailagent.mail.Msg;
import com.mailagent.store.ReminderStore;
import com.mailagent.store.SeenStore;
import com.mailagent.tools.AddReminderTool;
import com.mailagent.tools.CurrentDatetimeTool;
import com.mailagent.tools.FindItemsTool;
import com.mailagent.tools.Tool;
import com.mailagent.tools.ToolRegistry;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import org.slf4j.LoggerFactory;

import java.io.File;
import java.time.Clock;
import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Runs full MailAgent cycles (success path and LLM-failure fallback path)
 * with an email body containing PII, and asserts that no logged event —
 * success or failure — ever contains the body text or the PII substring.
 * This is a security-invariant check on the existing WARN-only, event-key
 * logging design (ToolRegistry/MailAgent never pass raw args/bodies to
 * SLF4J), not a driver for new production code.
 */
public class MailAgentPiiLoggingTest {

    private static final String SENSITIVE_PHONE = "+7-900-123-45-67";
    private static final String SENSITIVE_BODY =
            "Мой номер телефона " + SENSITIVE_PHONE + ", напомни позвонить Ивану";

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    private ListAppender<ILoggingEvent> appender;
    private Logger rootLogger;

    @Before
    public void attachAppender() {
        appender = new ListAppender<>();
        appender.start();
        rootLogger = (Logger) LoggerFactory.getLogger(Logger.ROOT_LOGGER_NAME);
        rootLogger.addAppender(appender);
    }

    @After
    public void detachAppender() {
        rootLogger.detachAppender(appender);
    }

    @Test
    public void successfulReplyNeverLogsEmailBodyOrPii() throws Exception {
        MockLlmClient llmClient = new MockLlmClient(Collections.singletonList(
                new ChatResponse(Collections.singletonList(ContentBlock.text("Хорошо, напомню.")), "end_turn")));

        runCycleAndAssertNoLeak(llmClient, "id-pii-1");
    }

    @Test
    public void llmFailureFallbackNeverLogsEmailBodyOrPii() throws Exception {
        MockLlmClient llmClient = new MockLlmClient(Collections.emptyList());

        runCycleAndAssertNoLeak(llmClient, "id-pii-2");
    }

    private void runCycleAndAssertNoLeak(MockLlmClient llmClient, String msgId) throws Exception {
        ReminderStore store = new ReminderStore(new File(tmp.getRoot(), "reminders-" + msgId + ".json").toPath());
        Clock clock = Clock.systemUTC();
        ToolRegistry toolRegistry = new ToolRegistry(Arrays.<Tool>asList(
                new CurrentDatetimeTool(clock), new AddReminderTool(store), new FindItemsTool(store)));
        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry, 6);
        SeenStore seenStore = new SeenStore(new File(tmp.getRoot(), "seen-" + msgId + ".txt").toPath());
        AuditLogger auditLogger = new AuditLogger(new File(tmp.getRoot(), "audit-" + msgId + ".log").toPath(), null);

        Msg msg = new Msg(msgId, "user@example.com", "Личные данные", SENSITIVE_BODY);
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore, auditLogger, "You are Kolya.");

        agent.pollOnce();

        assertTrue("expected a reply to be sent", !mailChannel.replies().isEmpty());

        for (ILoggingEvent event : appender.list) {
            String formatted = event.getFormattedMessage();
            assertFalse("log event leaked email body: " + formatted, formatted.contains(SENSITIVE_BODY));
            assertFalse("log event leaked PII (phone number): " + formatted, formatted.contains(SENSITIVE_PHONE));
        }
    }
}

package com.mailagent.llm;

/**
 * Unchecked wrapper for LLM-transport failures (non-2xx HTTP, network error,
 * unparseable response) so MailAgent's generic RuntimeException catch turns
 * any of them into a graceful fallback reply instead of a crash.
 */
public class LlmException extends RuntimeException {

    public LlmException(String message) {
        super(message);
    }

    public LlmException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.mailagent.llm;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mailagent.support.Json;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.util.Iterator;
import java.util.List;

/**
 * {@link LlmClient} over the real Anthropic Messages API
 * (POST /v1/messages, x-api-key + anthropic-version headers). The system
 * prompt has no dedicated field here because the caller (ToolLoop) already
 * folds it into the first user message's content blocks — this class only
 * has to speak the wire format faithfully.
 */
public class AnthropicLlmClient implements LlmClient {

    private static final String ANTHROPIC_VERSION = "2023-06-01";
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
    private static final int DEFAULT_MAX_TOKENS = 1024;

    private final OkHttpClient httpClient;
    private final String endpoint;
    private final String model;
    private final String apiKey;

    public AnthropicLlmClient(OkHttpClient httpClient, String endpoint, String model, String apiKey) {
        this.httpClient = httpClient;
        this.endpoint = endpoint;
        this.model = model;
        this.apiKey = apiKey;
    }

    @Override
    public ChatResponse chat(List<ChatMessage> messages, List<ToolSpec> tools) {
        ObjectNode requestBody = Json.MAPPER.createObjectNode();
        requestBody.put("model", model);
        requestBody.put("max_tokens", DEFAULT_MAX_TOKENS);
        requestBody.set("messages", messagesToJson(messages));
        if (!tools.isEmpty()) {
            requestBody.set("tools", toolsToJson(tools));
        }

        Request request = new Request.Builder()
                .url(endpoint)
                .addHeader("x-api-key", apiKey)
                .addHeader("anthropic-version", ANTHROPIC_VERSION)
                .post(RequestBody.create(JSON, requestBody.toString()))
                .build();

        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            String responseText = body == null ? "" : body.string();
            if (!response.isSuccessful()) {
                throw new LlmException("Anthropic API returned HTTP " + response.code());
            }
            return parseResponse(responseText);
        } catch (IOException e) {
            throw new LlmException("Anthropic API call failed", e);
        }
    }

    private static ArrayNode messagesToJson(List<ChatMessage> messages) {
        ArrayNode array = Json.MAPPER.createArrayNode();
        for (ChatMessage message : messages) {
            ObjectNode node = array.addObject();
            node.put("role", message.getRole());
            ArrayNode content = node.putArray("content");
            for (ContentBlock block : message.getContent()) {
                content.add(contentBlockToJson(block));
            }
        }
        return array;
    }

    private static ObjectNode contentBlockToJson(ContentBlock block) {
        ObjectNode node = Json.MAPPER.createObjectNode();
        switch (block.getType()) {
            case "text":
                node.put("type", "text");
                node.put("text", block.getText());
                break;
            case "tool_use":
                node.put("type", "tool_use");
                node.put("id", block.getToolUseId());
                node.put("name", block.getToolName());
                node.set("input", block.getToolInput());
                break;
            case "tool_result":
                node.put("type", "tool_result");
                node.put("tool_use_id", block.getToolUseId());
                node.put("content", block.getToolResultContent());
                break;
            default:
                throw new LlmException("Unknown content block type: " + block.getType());
        }
        return node;
    }

    private static ArrayNode toolsToJson(List<ToolSpec> tools) {
        ArrayNode array = Json.MAPPER.createArrayNode();
        for (ToolSpec tool : tools) {
            ObjectNode node = array.addObject();
            node.put("name", tool.getName());
            node.put("description", tool.getDescription());
            node.set("input_schema", tool.getInputSchema());
        }
        return array;
    }

    private static ChatResponse parseResponse(String responseText) {
        JsonNode root;
        try {
            root = Json.MAPPER.readTree(responseText);
        } catch (IOException e) {
            throw new LlmException("Failed to parse Anthropic API response", e);
        }

        java.util.List<ContentBlock> blocks = new java.util.ArrayList<>();
        Iterator<JsonNode> elements = root.path("content").elements();
        while (elements.hasNext()) {
            blocks.add(contentBlockFromJson(elements.next()));
        }
        String stopReason = root.path("stop_reason").asText(null);
        return new ChatResponse(blocks, stopReason);
    }

    private static ContentBlock contentBlockFromJson(JsonNode node) {
        String type = node.path("type").asText("");
        switch (type) {
            case "text":
                return ContentBlock.text(node.path("text").asText(""));
            case "tool_use":
                return ContentBlock.toolUse(
                        node.path("id").asText(null),
                        node.path("name").asText(null),
                        node.path("input"));
            case "tool_result":
                return ContentBlock.toolResult(
                        node.path("tool_use_id").asText(null),
                        node.path("content").asText(null));
            default:
                throw new LlmException("Unknown content block type in Anthropic response: " + type);
        }
    }
}

package com.mailagent.llm;

import com.fasterxml.jackson.databind.JsonNode;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Exercises the real Anthropic Messages API wire format against a
 * MockWebServer instance — no network, no real API key, deterministic and
 * fast enough to run in `mvn test` on any machine.
 */
public class AnthropicLlmClientTest {

    private MockWebServer server;

    @Before
    public void startServer() throws Exception {
        server = new MockWebServer();
        server.start();
    }

    @After
    public void stopServer() throws Exception {
        server.shutdown();
    }

    @Test
    public void sendsCorrectlyShapedRequest() throws Exception {
        server.enqueue(new MockResponse().setBody(
                "{\"content\":[{\"type\":\"text\",\"text\":\"hi\"}],\"stop_reason\":\"end_turn\"}"));

        AnthropicLlmClient client = new AnthropicLlmClient(
                new OkHttpClient(), server.url("/v1/messages").toString(), "claude-sonnet-5", "test-api-key");

        List<ChatMessage> messages = Collections.singletonList(
                ChatMessage.user(Collections.singletonList(ContentBlock.text("Hello"))));
        List<ToolSpec> tools = Collections.singletonList(
                ToolSpec.from(new com.mailagent.tools.CurrentDatetimeTool(java.time.Clock.systemUTC())));

        client.chat(messages, tools);

        RecordedRequest request = server.takeRequest();
        assertEquals("POST", request.getMethod());
        assertEquals("/v1/messages", request.getPath());
        assertEquals("test-api-key", request.getHeader("x-api-key"));
        assertEquals("2023-06-01", request.getHeader("anthropic-version"));

        JsonNode body = com.mailagent.support.Json.MAPPER.readTree(request.getBody().readUtf8());
        assertEquals("claude-sonnet-5", body.get("model").asText());
        assertEquals("user", body.get("messages").get(0).get("role").asText());
        assertEquals("Hello", body.get("messages").get(0).get("content").get(0).get("text").asText());
        assertEquals("current_datetime", body.get("tools").get(0).get("name").asText());
    }

    @Test
    public void parsesToolUseResponse() throws Exception {
        server.enqueue(new MockResponse().setBody(
                "{\"content\":[{\"type\":\"tool_use\",\"id\":\"toolu_1\",\"name\":\"current_datetime\",\"input\":{}}],"
                        + "\"stop_reason\":\"tool_use\"}"));

        AnthropicLlmClient client = new AnthropicLlmClient(
                new OkHttpClient(), server.url("/v1/messages").toString(), "claude-sonnet-5", "test-api-key");

        ChatResponse response = client.chat(
                Collections.singletonList(ChatMessage.user(Collections.singletonList(ContentBlock.text("What time is it?")))),
                Collections.emptyList());

        assertTrue(response.hasToolUse());
        assertEquals("tool_use", response.getStopReason());
        ContentBlock toolUse = response.toolUseBlocks().get(0);
        assertEquals("toolu_1", toolUse.getToolUseId());
        assertEquals("current_datetime", toolUse.getToolName());
    }

    @Test
    public void parsesTextOnlyResponse() throws Exception {
        server.enqueue(new MockResponse().setBody(
                "{\"content\":[{\"type\":\"text\",\"text\":\"Today is Thursday.\"}],\"stop_reason\":\"end_turn\"}"));

        AnthropicLlmClient client = new AnthropicLlmClient(
                new OkHttpClient(), server.url("/v1/messages").toString(), "claude-sonnet-5", "test-api-key");

        ChatResponse response = client.chat(
                Collections.singletonList(ChatMessage.user(Collections.singletonList(ContentBlock.text("What day is it?")))),
                Collections.emptyList());

        assertFalse(response.hasToolUse());
        assertEquals("Today is Thursday.", response.textJoined());
    }

    @Test
    public void nonSuccessfulHttpResponseThrows() throws Exception {
        server.enqueue(new MockResponse().setResponseCode(500).setBody("{\"error\":\"internal\"}"));

        AnthropicLlmClient client = new AnthropicLlmClient(
                new OkHttpClient(), server.url("/v1/messages").toString(), "claude-sonnet-5", "test-api-key");

        try {
            client.chat(Collections.singletonList(
                    ChatMessage.user(Collections.singletonList(ContentBlock.text("Hi")))), Collections.emptyList());
            fail("Expected LlmException on non-2xx response");
        } catch (LlmException expected) {
            // expected: MailAgent's catch(RuntimeException) turns this into a graceful fallback
        }
    }

    @Test
    public void toolResultMessageIsSerializedCorrectly() throws Exception {
        server.enqueue(new MockResponse().setBody(
                "{\"content\":[{\"type\":\"text\",\"text\":\"done\"}],\"stop_reason\":\"end_turn\"}"));

        AnthropicLlmClient client = new AnthropicLlmClient(
                new OkHttpClient(), server.url("/v1/messages").toString(), "claude-sonnet-5", "test-api-key");

        List<ChatMessage> messages = Arrays.asList(
                ChatMessage.user(Collections.singletonList(ContentBlock.text("What time is it?"))),
                ChatMessage.assistant(Collections.singletonList(
                        ContentBlock.toolUse("toolu_1", "current_datetime", com.mailagent.support.Json.MAPPER.createObjectNode()))),
                ChatMessage.user(Collections.singletonList(ContentBlock.toolResult("toolu_1", "2026-08-13T09:00:00Z"))));

        client.chat(messages, Collections.emptyList());

        RecordedRequest request = server.takeRequest();
        JsonNode body = com.mailagent.support.Json.MAPPER.readTree(request.getBody().readUtf8());
        JsonNode toolResultBlock = body.get("messages").get(2).get("content").get(0);
        assertEquals("tool_result", toolResultBlock.get("type").asText());
        assertEquals("toolu_1", toolResultBlock.get("tool_use_id").asText());
        assertEquals("2026-08-13T09:00:00Z", toolResultBlock.get("content").asText());
    }
}

package com.mailagent.agent;

import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mailagent.audit.AuditLogger;
import com.mailagent.llm.ChatResponse;
import com.mailagent.llm.ContentBlock;
import com.mailagent.llm.MockLlmClient;
import com.mailagent.mail.MailChannel;
import com.mailagent.mail.MailException;
import com.mailagent.mail.MockMailChannel;
import com.mailagent.mail.Msg;
import com.mailagent.store.ReminderStore;
import com.mailagent.store.SeenStore;
import com.mailagent.support.Json;
import com.mailagent.tools.AddReminderTool;
import com.mailagent.tools.CurrentDatetimeTool;
import com.mailagent.tools.FindItemsTool;
import com.mailagent.tools.Tool;
import com.mailagent.tools.ToolRegistry;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers the four golden scenarios from the assignment (§10: reminder, list,
 * date, junk mail) plus the two core robustness requirements — LLM-failure
 * fallback and idempotency across poll cycles — all against MockMailChannel
 * and MockLlmClient with the real tool implementations wired in.
 */
public class MailAgentTest {

    private static final String SYSTEM_PROMPT = "You are Kolya, an email assistant.";

    @Rule
    public TemporaryFolder tmp = new TemporaryFolder();

    @Test
    public void reminderEmailTriggersAddReminderAndConfirmationReply() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        ObjectNode toolInput = Json.MAPPER.createObjectNode();
        toolInput.put("text", "позвонить Ивану");
        toolInput.put("dueIso", "2026-08-14T10:00:00Z");

        MockLlmClient llmClient = new MockLlmClient(Arrays.asList(
                new ChatResponse(Collections.singletonList(
                        ContentBlock.toolUse("call-1", "add_reminder", toolInput)), "tool_use"),
                new ChatResponse(Collections.singletonList(
                        ContentBlock.text("Напомню: позвонить Ивану 14.08 в 10:00.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-1", "user@example.com", "Напоминание", "Напомни завтра в 10 позвонить Ивану");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore(), auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
        assertEquals("Напомню: позвонить Ивану 14.08 в 10:00.", mailChannel.replies().get(0).getBody());
        assertEquals(1, store.list().size());
        assertEquals("позвонить Ивану", store.list().get(0).getText());
    }

    @Test
    public void listEmailTriggersFindItemsAndListReply() throws Exception {
        ReminderStore store = reminderStore();
        store.add("позвонить Ивану", "2026-08-14T10:00:00Z");
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        ObjectNode toolInput = Json.MAPPER.createObjectNode();
        toolInput.put("query", "Иван");

        MockLlmClient llmClient = new MockLlmClient(Arrays.asList(
                new ChatResponse(Collections.singletonList(
                        ContentBlock.toolUse("call-1", "find_items", toolInput)), "tool_use"),
                new ChatResponse(Collections.singletonList(
                        ContentBlock.text("У вас запланировано: позвонить Ивану.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-2", "user@example.com", "Планы", "Что у меня запланировано?");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore(), auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
        assertEquals("У вас запланировано: позвонить Ивану.", mailChannel.replies().get(0).getBody());
    }

    @Test
    public void dateEmailTriggersCurrentDatetimeReply() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        MockLlmClient llmClient = new MockLlmClient(Arrays.asList(
                new ChatResponse(Collections.singletonList(
                        ContentBlock.toolUse("call-1", "current_datetime", Json.MAPPER.createObjectNode())), "tool_use"),
                new ChatResponse(Collections.singletonList(
                        ContentBlock.text("Сегодня 13 августа 2026 года.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-3", "user@example.com", "Дата", "Какое сегодня число?");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore(), auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
        assertEquals("Сегодня 13 августа 2026 года.", mailChannel.replies().get(0).getBody());
    }

    @Test
    public void junkEmailGetsGracefulReplyWithoutToolCalls() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        MockLlmClient llmClient = new MockLlmClient(Collections.singletonList(
                new ChatResponse(Collections.singletonList(
                        ContentBlock.text("Извините, не понял ваш запрос.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-4", "spam@example.com", "", "");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore(), auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
        assertEquals("Извините, не понял ваш запрос.", mailChannel.replies().get(0).getBody());
        assertTrue(store.list().isEmpty());
        assertEquals(1, llmClient.requests().size());
    }

    @Test
    public void llmFailureFallsBackToGracefulReplyAndStillMarksSeen() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        MockLlmClient llmClient = new MockLlmClient(Collections.emptyList());

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-5", "user@example.com", "Напоминание", "Напомни позвонить");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        SeenStore seenStore = seenStore();
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore, auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
        assertFalse(mailChannel.replies().get(0).getBody().isEmpty());
        assertTrue(seenStore.isSeen("id-5"));
    }

    @Test
    public void sameMessageIsNotRepliedToTwiceAcrossPolls() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        MockLlmClient llmClient = new MockLlmClient(Collections.singletonList(
                new ChatResponse(Collections.singletonList(ContentBlock.text("Ok.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-6", "user@example.com", "Subject", "Body");
        MockMailChannel mailChannel = new MockMailChannel(Collections.singletonList(msg));
        MailAgent agent = new MailAgent(mailChannel, toolLoop, seenStore(), auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();
        agent.pollOnce();

        assertEquals(1, mailChannel.replies().size());
    }

    @Test
    public void mailReplyFailureLeavesMessageUnseenForRetry() throws Exception {
        ReminderStore store = reminderStore();
        Clock clock = Clock.fixed(Instant.parse("2026-08-13T09:00:00Z"), ZoneOffset.UTC);

        MockLlmClient llmClient = new MockLlmClient(Collections.singletonList(
                new ChatResponse(Collections.singletonList(ContentBlock.text("Ok.")), "end_turn")));

        ToolLoop toolLoop = new ToolLoop(llmClient, toolRegistry(store, clock), 6);
        Msg msg = new Msg("id-7", "user@example.com", "Subject", "Body");
        MailChannel failingChannel = new FailingReplyMailChannel(Collections.singletonList(msg));
        SeenStore seenStore = seenStore();
        MailAgent agent = new MailAgent(failingChannel, toolLoop, seenStore, auditLogger(), SYSTEM_PROMPT);

        agent.pollOnce();

        assertFalse(seenStore.isSeen("id-7"));
    }

    private ToolRegistry toolRegistry(ReminderStore store, Clock clock) {
        return new ToolRegistry(Arrays.<Tool>asList(
                new CurrentDatetimeTool(clock),
                new AddReminderTool(store),
                new FindItemsTool(store)));
    }

    private SeenStore seenStore() throws Exception {
        return new SeenStore(new File(tmp.getRoot(), "seen.txt").toPath());
    }

    private AuditLogger auditLogger() throws Exception {
        return new AuditLogger(new File(tmp.getRoot(), "audit.log").toPath(), null);
    }

    private ReminderStore reminderStore() throws Exception {
        return new ReminderStore(new File(tmp.getRoot(), "reminders.json").toPath());
    }

    private static final class FailingReplyMailChannel implements MailChannel {
        private final List<Msg> unread;

        FailingReplyMailChannel(List<Msg> unread) {
            this.unread = unread;
        }

        @Override
        public List<Msg> fetchUnread() {
            return unread;
        }

        @Override
        public void reply(Msg msg, String body) {
            throw new MailException("simulated COM failure");
        }
    }
}

