1	package com.mailagent.agent;
2	
3	import com.mailagent.audit.AuditLogger;
4	import com.mailagent.mail.MailChannel;
5	import com.mailagent.mail.MailException;
6	import com.mailagent.mail.Msg;
7	import com.mailagent.store.SeenStore;
8	import org.slf4j.Logger;
9	import org.slf4j.LoggerFactory;
10	
11	import java.io.IOException;
12	
13	/**
14	 * Drives one poll cycle: fetch unread mail, skip anything already seen, run
15	 * the tool loop for the rest, reply, then mark seen. A message is only ever
16	 * marked seen once we've actually sent a reply for it — if the LLM/tool loop
17	 * blows up we still send a graceful fallback and mark it seen (so a broken
18	 * model can't make the same email spam a fallback every cycle forever); if
19	 * sending the reply itself fails (COM error), we leave it unseen so the next
20	 * poll retries it.
21	 */
22	public class MailAgent {
23	
24	    private static final Logger log = LoggerFactory.getLogger(MailAgent.class);
25	
26	    private static final String FALLBACK_REPLY =
27	            "Извините, не удалось обработать ваш запрос из-за временной технической проблемы. Мы вернёмся к нему позже.";
28	
29	    private final MailChannel mailChannel;
30	    private final ToolLoop toolLoop;
31	    private final SeenStore seenStore;
32	    private final AuditLogger auditLogger;
33	    private final String systemPrompt;
34	
35	    public MailAgent(MailChannel mailChannel, ToolLoop toolLoop, SeenStore seenStore,
36	                      AuditLogger auditLogger, String systemPrompt) {
37	        this.mailChannel = mailChannel;
38	        this.toolLoop = toolLoop;
39	        this.seenStore = seenStore;
40	        this.auditLogger = auditLogger;
41	        this.systemPrompt = systemPrompt;
42	    }
43	
44	    public void pollOnce() {
45	        for (Msg msg : mailChannel.fetchUnread()) {
46	            if (seenStore.isSeen(msg.getId())) {
47	                continue;
48	            }
49	            processOne(msg);
50	        }
51	    }
52	
53	    private void processOne(Msg msg) {
54	        String replyBody;
55	        try {
56	            replyBody = toolLoop.run(systemPrompt, msg.getBody());
57	        } catch (RuntimeException e) {
